"""Integration coverage for part partitions, run with unittest discovery."""
from pathlib import Path
import subprocess
import sys
import unittest

SCENARIO = "\nimport os,tempfile,sqlite3\nfrom pathlib import Path\ntest_dir=tempfile.TemporaryDirectory(prefix='wiareport-parts-test-',dir='/tmp')\nroot=Path(test_dir.name)\nos.environ['WIAREPORT_DATA_DIR']=str(root)\nfrom backend import main as m\nfrom tests.credential_support import TestClient, TEST_PASSWORD\nm.init_db()\nclient=TestClient(m.app)\ndef check(r,status=200):\n assert r.status_code==status,(r.status_code,r.text)\n return r.json() if r.content else None\nteam=check(client.post('/api/teams',json={'department':'파트 테스트','login_id':'parts-test'}),201)['team_id']\nother=check(client.post('/api/teams',json={'department':'별도 팀','login_id':'other-test'}),201)['team_id']\nbase='/api/teams/'+team\ndef headers(part=''): return {'X-Wia-Team':team,'X-Wia-Part':part}\nu0=check(client.post(base+'/users',headers=headers(),json={'name':'기존 멤버','role':'M'}),201)\nassert u0['part_id'] is None\nassert not check(client.get(base+'/parts'))['enabled']\ncheck(client.put(base+'/parts/settings',json={'enabled':True}))\na=check(client.post(base+'/parts',json={'name':'A파트'}),201)['parts'][0]['part_id']\nb=check(client.post(base+'/parts',json={'name':'B파트'}),201)['parts'][1]['part_id']\ncheck(client.post(base+'/parts',json={'name':' A파트 '}),409)\ncheck(client.post(base+'/parts',json={'name':' '}),422)\nusers={}\nprojects={}\nreports={}\nfor part in [a,b]:\n h=headers(part)\n u=check(client.post(base+'/users',headers=h,json={'name':'구성원','role':'M'}),201)\n users[part]=u;assert u['part_id']==part\n p=check(client.post(base+'/team-projects',headers=h,json={'project_name':'공통 이름','members':[{'user_id':u['user_id'],'role':'M'}]}),201)\n projects[part]=p;assert p['part_id']==part\n event=check(client.post(base+'/events',headers=h,json={'title':'일정','event_type':'vacation','start_date':'2026-09-14','end_date':'2026-09-18','member_ids':[u['user_id']]}),201)\n assert event['part_id']==part\n report=check(client.post(base+'/reports',headers=h,json={'start_date':'2026-09-14','end_date':'2026-09-18'}),201)\n reports[part]=report\n assert report['part_id']==part\n assert [x['user_id'] for x in report['members']]==[u['user_id']]\n assert len(check(client.get(base+'/users',headers=h)))==1\n assert len(check(client.get(base+'/events',headers=h)))==1\n assert len(check(client.get(base+'/team-projects',headers=h)))==1\n assert len(check(client.get(base+'/reports/active-list',headers=h)))==1\n check(client.put(base+'/report-schedule',headers=h,json={'enabled':True,'weekday':2,'time':'09:00','interval_days':7}))\n assert check(client.get(base+'/report-schedule',headers=h))['weekday']==2\n assert len(check(client.get(base+'/timeline-projects',headers=h)))==1\ncheck(client.get('/api/users/'+users[b]['user_id']+'/role',headers=headers(a)),404) # middleware blocks even invalid method\ncheck(client.put('/api/users/'+users[b]['user_id']+'/role',headers=headers(a),json={'role':'CM'}),404)\ncheck(client.put('/api/team-projects/'+projects[b]['project_id']+'/status',headers=headers(a),json={'status':'done'}),404)\ncheck(client.put('/api/reports/'+reports[b]['report_id']+'/reopen',headers=headers(a)),404)\ncheck(client.get(base+'/users',headers={'X-Wia-Team':other,'X-Wia-Part':a}),404)\ncheck(client.get(base+'/users',headers=headers('not-a-part')),409)\ncheck(client.post(base+'/team-projects',headers=headers(a),json={'project_name':'invalid','members':[{'user_id':users[b]['user_id'],'role':'M'}]}),422)\ncheck(client.post(base+'/events',headers=headers(a),json={'title':'invalid','event_type':'vacation','start_date':'2026-09-14','end_date':'2026-09-18','member_ids':[users[b]['user_id']]}),422)\nassert [u['user_id'] for u in check(client.get(base+'/users',headers=headers()))]==[u0['user_id']]\nassert check(client.get(base+'/reports/active-list',headers=headers()))==[]\nfor part in [a,b]:\n result=check(client.post('/api/reports/'+reports[part]['report_id']+'/users/'+users[part]['user_id']+'/authorize',headers=headers(part),json={'password':TEST_PASSWORD}))\n assert len(result['projects'])==2,result\n with m.get_conn() as c:\n  assert c.execute(\"SELECT part_id FROM project WHERE project_name=? AND part_id=?\",(m.OTHER_WORK_PROJECT_NAME,part)).fetchone()\ncheck(client.delete(base+'/parts/'+a),409)\ncheck(client.put(base+'/parts/settings',json={'enabled':False}))\nassert len(check(client.get(base+'/users',headers=headers())))==3\ncheck(client.get(base+'/users',headers=headers(a)),409)\nassert len(check(client.get(base+'/team-projects',headers=headers())))==2\ncheck(client.put(base+'/parts/settings',json={'enabled':True}))\nassert len(check(client.get(base+'/users',headers=headers(a))))==1\n\n# Independent schedules generate one report per part per period.\nfrom datetime import datetime\ncreated=m.create_due_weekly_reports(datetime(2026,9,16,10,0,tzinfo=m.KST))\nassert m.create_due_weekly_reports(datetime(2026,9,16,10,0,tzinfo=m.KST))==[]\nfor part in [a,b]:\n assert any(r['start_date']=='2026-09-16' for r in check(client.get(base+'/reports/active-list',headers=headers(part))))\n# A team-wide report made while parts are disabled retains all its participants after re-enabling.\ncheck(client.put(base+'/parts/settings',json={'enabled':False}))\ncombined=check(client.post(base+'/reports',headers=headers(),json={'start_date':'2026-10-01','end_date':'2026-10-07'}),201)\nassert len(combined['members'])==3\ncheck(client.post('/api/reports/'+combined['report_id']+'/users/'+users[a]['user_id']+'/authorize',headers=headers(),json={'password':TEST_PASSWORD}))\ncheck(client.put(base+'/parts/settings',json={'enabled':True}))\ncheck(client.post('/api/reports/'+combined['report_id']+'/users/'+users[a]['user_id']+'/authorize',headers=headers(),json={'password':TEST_PASSWORD}))\nauth=check(client.post('/api/reports/'+combined['report_id']+'/users/'+users[b]['user_id']+'/authorize',headers=headers(),json={'password':TEST_PASSWORD}))\nassert len(auth['projects'])==2\n# Nested milestone/work access is bounded by its project part.\nms=check(client.post('/api/projects/'+projects[a]['project_id']+'/milestones',headers=headers(a),json={'title':'마일스톤','start_date':'2026-09-14','end_date':'2026-09-18'}),201)\nep=check(client.post('/api/milestones/'+ms['id']+'/epics',headers=headers(a),json={'title':'워크','start_date':'2026-09-14','end_date':'2026-09-18'}),201)\ncheck(client.get('/api/milestones/'+ms['id'],headers=headers(b)),404)\ncheck(client.delete('/api/epics/'+ep['id'],headers=headers(b)),404)\nassert check(client.get('/api/milestones',headers=headers(b)))==[]\nassert len(check(client.get('/api/milestones',headers=headers(a))))==1\nm.init_db()\nassert len(check(client.get(base+'/users',headers=headers(a))))==1\nwith m.get_conn() as c: assert c.execute('PRAGMA foreign_key_check').fetchall()==[]\nprint('PASS: part CRUD/toggle, NULL legacy data, member/project/event/report isolation, references, direct-ID scope checks, schedules, other-work, migration persistence')\n"

class PartIntegrationTests(unittest.TestCase):
    def test_parts_preserve_and_isolate_workspaces(self):
        result = subprocess.run(
            [sys.executable, "-W", "ignore::DeprecationWarning", "-c", SCENARIO],
            cwd=Path(__file__).resolve().parents[1],
            capture_output=True, text=True, timeout=60,
        )
        self.assertEqual(result.returncode, 0, result.stdout + result.stderr)

if __name__ == "__main__":
    unittest.main()
